style.css:
* {
    /* 合并写法，更简洁 */
    
    /* 强制细体 (注意：这会使标题和重点文字也变细) */
    font-weight: 400 !important;
    
    /* 优化后的阴影：使用 currentColor 让阴影跟随文字颜色，自动适应黑暗模式 */
    /* transparent 0.1 的透明度能模拟出你要的 #999999 效果，但更智能 */
    text-shadow: 0.1px 0.1px 1px rgba(0, 0, 0, 0.2) !important;
    
    /* 开启抗锯齿，这是不换字体也能让文字变精致的关键 */
    -webkit-font-smoothing: antialiased !important;
}
